import{_ as e,o as n,c as t,a2 as s}from"./chunks/framework.B7wGsJGy.js";const m=JSON.parse('{"title":"npm、Yarn、pnpm 与依赖管理","description":"","frontmatter":{},"headers":[],"relativePath":"概念与原理/05node/s_node_4-package_management.md","filePath":"概念与原理/05node/s_node_4-package_management.md","lastUpdated":1794382705000}'),d={name:"概念与原理/05node/s_node_4-package_management.md"};function p(r,a,i,o,l,c){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="npm、yarn、pnpm-与依赖管理" tabindex="-1">npm、Yarn、pnpm 与依赖管理 <a class="header-anchor" href="#npm、yarn、pnpm-与依赖管理" aria-label="Permalink to &quot;npm、Yarn、pnpm 与依赖管理&quot;">​</a></h1><blockquote><p>包管理器的目标不只是“把包下载下来”，还包括解析版本、组织依赖关系，以及让团队和构建环境尽可能复现同一套依赖。</p></blockquote><h2 id="一、先区分几个概念" tabindex="-1">一、先区分几个概念 <a class="header-anchor" href="#一、先区分几个概念" aria-label="Permalink to &quot;一、先区分几个概念&quot;">​</a></h2><ul><li><strong>npm registry</strong>：包的分发服务，npm、Yarn、pnpm 都可以访问兼容的 registry。</li><li><strong>npm CLI</strong>：一个包管理工具，不等于 registry 本身。</li><li><strong>package.json</strong>：声明包的元信息、脚本与依赖约束。</li><li><strong>锁文件</strong>：记录解析出的依赖图、具体版本及完整性等信息，具体字段依工具与格式而异。</li><li><strong>node_modules / PnP</strong>：依赖在本地如何布局和被解析，不等于“下载源”。</li></ul><h2 id="二、package-json-中最重要的字段" tabindex="-1">二、package.json 中最重要的字段 <a class="header-anchor" href="#二、package-json-中最重要的字段" aria-label="Permalink to &quot;二、package.json 中最重要的字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>用途</th><th>注意点</th></tr></thead><tbody><tr><td><code>scripts</code></td><td>定义开发、检查与构建等命令</td><td><code>build</code> 做什么取决于脚本，不是 Node.js 自动赋予的能力</td></tr><tr><td><code>dependencies</code></td><td>通常用于运行或交付所需依赖</td><td>前端打包项目与服务端部署项目的需求不完全相同</td></tr><tr><td><code>devDependencies</code></td><td>开发、检查、构建等工具</td><td>构建阶段仍需这些依赖，不能过早只安装生产依赖</td></tr><tr><td><code>peerDependencies</code></td><td>声明期望由使用方提供的兼容依赖</td><td>常见于插件、组件库；实际安装策略因工具版本而异</td></tr><tr><td><code>engines</code></td><td>声明支持的 Node / 包管理器范围</td><td>是否严格阻止不兼容安装，取决于工具设置</td></tr><tr><td><code>packageManager</code></td><td>声明项目约定的工具与版本</td><td>需要开发环境和自动化真正使用该版本</td></tr><tr><td><code>type</code></td><td>确定包中 <code>.js</code> 的模块格式</td><td>不控制 <code>.mjs</code> / <code>.cjs</code> 的显式格式</td></tr><tr><td><code>exports</code></td><td>定义包对外的入口与子路径</td><td>有助于限制内部实现被随意导入，也影响 ESM/CJS 入口</td></tr><tr><td><code>private</code></td><td>防止意外发布包</td><td>不等于把源代码变成保密内容</td></tr></tbody></table><p>包的类型由使用目的决定，不能认为 <code>devDependencies</code> 中的代码永远不会出现在最终前端产物；只要被构建链引入，仍可能进入输出。</p><h2 id="三、版本范围与锁文件" tabindex="-1">三、版本范围与锁文件 <a class="header-anchor" href="#三、版本范围与锁文件" aria-label="Permalink to &quot;三、版本范围与锁文件&quot;">​</a></h2><p>以稳定主版本 <code>1.2.3</code> 为例：</p><table tabindex="0"><thead><tr><th>写法</th><th>常见含义</th></tr></thead><tbody><tr><td><code>1.2.3</code></td><td>精确版本</td></tr><tr><td><code>~1.2.3</code></td><td>通常允许补丁更新，即 <code>&gt;=1.2.3 &lt;1.3.0</code></td></tr><tr><td><code>^1.2.3</code></td><td>通常允许向后兼容的次版本和补丁更新，即 <code>&gt;=1.2.3 &lt;2.0.0</code></td></tr><tr><td><code>workspace:*</code></td><td>以支持该协议的工具解析本工作区包</td></tr></tbody></table><p><code>0.x</code> 版本的 caret 范围更收敛，例如 <code>^0.2.3</code> 通常不跨到 <code>0.3.0</code>；预发布版本也有额外规则。即便版本遵循 SemVer，升级后仍要验证，不应只凭版本号认定完全兼容。</p><p>锁文件固定的是解析结果，<code>package.json</code> 说明可接受范围，二者需要一起维护。手改约束后不更新锁文件，冻结安装通常会拒绝继续。</p><p><strong>可重复安装仍有环境边界</strong>：Node 版本、包管理器版本、操作系统、CPU 架构、原生模块、可选依赖以及安装脚本，都可能影响结果。锁文件是基础，不是跨所有环境完全相同的保证。</p><h2 id="四、三种工具的依赖布局" tabindex="-1">四、三种工具的依赖布局 <a class="header-anchor" href="#四、三种工具的依赖布局" aria-label="Permalink to &quot;四、三种工具的依赖布局&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具 / 模式</th><th>常见特征</th><th>需要注意</th></tr></thead><tbody><tr><td>npm</td><td>常见使用 <code>node_modules</code> 和提升去重</td><td>某些间接依赖可能恰好可访问，不应依赖这种布局偶然性</td></tr><tr><td>Yarn</td><td>不同代际差异较大；现代 Yarn 可选择 PnP 或 node_modules linker</td><td>不能把所有 Yarn 都描述为同一种扁平目录</td></tr><tr><td>pnpm</td><td>常见使用内容寻址存储、虚拟存储及链接组织依赖图</td><td>对直接依赖边界通常更严格，仍受 hoist/linker 等设置影响</td></tr></tbody></table><h3 id="pnpm-为什么能节省磁盘" tabindex="-1">pnpm 为什么能节省磁盘？ <a class="header-anchor" href="#pnpm-为什么能节省磁盘" aria-label="Permalink to &quot;pnpm 为什么能节省磁盘？&quot;">​</a></h3><p>常见安装模式下，pnpm 把包文件放入可复用的内容寻址存储，通过硬链接或写时复制等方式复用文件（受文件系统与配置影响），在项目的虚拟存储中组织包，再使用符号链接表达依赖关系。</p><p>因此不能简单记成“所有文件都是软链接”，也不能认为它只解决下载速度；依赖关系的隔离与共享存储同样重要。</p><h3 id="什么是幽灵依赖" tabindex="-1">什么是幽灵依赖？ <a class="header-anchor" href="#什么是幽灵依赖" aria-label="Permalink to &quot;什么是幽灵依赖？&quot;">​</a></h3><p>某个包没有在当前包中声明，却因为其他依赖被提升等原因恰好能够导入，称为幽灵依赖或未声明依赖。换工具、升级或改变工作区布局后可能失效。</p><p>正确做法是：<strong>在哪个包中直接使用，就在那个包中显式声明。</strong> 不要通过盲目开启全面提升来掩盖依赖声明问题。</p><h2 id="五、本项目如何使用" tabindex="-1">五、本项目如何使用？ <a class="header-anchor" href="#五、本项目如何使用" aria-label="Permalink to &quot;五、本项目如何使用？&quot;">​</a></h2><p>本项目当前约定 Node.js 24.x、pnpm 12.14.0，具体以 <code>.nvmrc</code>、<code>package.json</code> 和锁文件为准。下面仅说明现有流程，不修改工具或发布配置。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 按现有锁文件安装；不擅自更新解析结果</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 开发、校验、构建</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看某个依赖为何被引入</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> why</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>新增依赖前先判断是不是 Node.js 内置能力、已有依赖是否足够。确需添加时，在正确的包中声明，提交 <code>package.json</code> 与 <code>pnpm-lock.yaml</code>，并验证兼容性。</p><p><strong>不要在同一项目中混用 npm、Yarn 和 pnpm 生成多份相互竞争的锁文件。</strong> 更换工具属于一次有验证要求的迁移，不是换一条安装命令。</p><h2 id="六、开发、构建与运行是不同阶段" tabindex="-1">六、开发、构建与运行是不同阶段 <a class="header-anchor" href="#六、开发、构建与运行是不同阶段" aria-label="Permalink to &quot;六、开发、构建与运行是不同阶段&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开发：源码 + 类型检查 / lint / 本地服务</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>构建：安装构建所需依赖，转换或打包源码</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>交付：发布实际产物，以及运行所需的文件与依赖</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>前端静态站点构建后可以只部署静态文件；Node.js 服务通常仍需要 Node 运行时，是否需要运行时依赖取决于构建产物是否外部化依赖等策略。不能因为项目都用 pnpm，就把交付方式混为一谈。</p><p>Monorepo 可以统一管理多个应用与共享包，但不是把所有依赖都堆进根目录。每个包要声明自己的依赖，构建顺序、包边界与发布策略也要明确。</p><h2 id="七、依赖安全与维护" tabindex="-1">七、依赖安全与维护 <a class="header-anchor" href="#七、依赖安全与维护" aria-label="Permalink to &quot;七、依赖安全与维护&quot;">​</a></h2><ul><li>安装脚本可以执行代码，新增依赖前要评估来源、维护情况和脚本行为；不随意放开所有脚本权限。</li><li>完整性校验能帮助验证下载内容是否符合锁定结果，但不证明包本身没有恶意逻辑。</li><li>安全审计是发现已知风险的线索，仍需判断实际使用路径、影响版本和修复兼容性。</li><li>升级最好分批进行，先读变更说明，再运行类型检查、测试和构建；不要为追逐“最新”而绕过框架的兼容依赖组合。</li></ul><h2 id="八、学习回顾" tabindex="-1">八、学习回顾 <a class="header-anchor" href="#八、学习回顾" aria-label="Permalink to &quot;八、学习回顾&quot;">​</a></h2><blockquote><p>npm、Yarn、pnpm 都能管理依赖，但本地布局和解析策略不同。package.json 描述依赖范围，锁文件记录具体解析结果；要让团队安装可重复，还得统一 Node 和包管理器版本。pnpm 常通过共享内容存储和链接组织依赖，节约磁盘，并减少未声明依赖被偶然访问的问题。项目中我会坚持一种工具、一份对应锁文件，升级后验证真实构建和运行。</p></blockquote><p><strong>自测：</strong> 为什么提交了锁文件还要统一 Node 版本？<code>pnpm why</code> 能解释什么？构建前只安装生产依赖为什么可能失败？Monorepo 子包为什么仍要声明自己的依赖？</p><blockquote><p>来源：<a href="https://docs.npmjs.com/cli/v11/configuring-npm/package-json" target="_blank" rel="noreferrer">npm package.json</a>、<a href="https://docs.npmjs.com/cli/v11/using-npm/semver" target="_blank" rel="noreferrer">npm SemVer</a>、<a href="https://pnpm.io/symlinked-node-modules-structure" target="_blank" rel="noreferrer">pnpm 的依赖布局</a>、<a href="https://pnpm.io/cli/install" target="_blank" rel="noreferrer">pnpm install</a>、<a href="https://yarnpkg.com/features/linkers" target="_blank" rel="noreferrer">Yarn Linkers</a></p></blockquote>`,36)])])}const k=e(d,[["render",p]]);export{m as __pageData,k as default};
